// Generated by `npx crashheal init`. Forwards Crashlytics alerts to GitHub as repository_dispatch events.
const {
  onNewFatalIssuePublished,
  onNewNonfatalIssuePublished,
  onNewAnrIssuePublished,
  onRegressionAlertPublished,
} = require("firebase-functions/v2/alerts/crashlytics");
const { defineSecret } = require("firebase-functions/params");
const logger = require("firebase-functions/logger");

const GITHUB_TOKEN = defineSecret("CRASHHEAL_GITHUB_TOKEN");
const REPO = "OWNER/REPO";
// Only forward alerts for these apps (empty = all apps in the project).
const APP_IDS = ["1:74309595644:android:520475bd53213160e0c279"];

function forward(type) {
  return async (event) => {
    if (APP_IDS.length && !APP_IDS.includes(event.appId)) return;
    const issue = (event.data && event.data.payload && event.data.payload.issue) || {};
    const body = {
      event_type: "crashlytics-issue",
      client_payload: {
        type,
        appId: event.appId,
        issueId: issue.id,
        title: issue.title,
        subtitle: issue.subtitle,
        appVersion: issue.appVersion,
      },
    };
    const res = await fetch(`https://api.github.com/repos/${REPO}/dispatches`, {
      method: "POST",
      headers: {
        Authorization: `Bearer ${GITHUB_TOKEN.value()}`,
        Accept: "application/vnd.github+json",
        "X-GitHub-Api-Version": "2022-11-28",
        "User-Agent": "crashheal-functions",
      },
      body: JSON.stringify(body),
    });
    if (!res.ok) {
      logger.error("GitHub dispatch failed", { status: res.status, body: await res.text() });
      throw new Error(`GitHub dispatch failed: ${res.status}`);
    }
    logger.info("Forwarded Crashlytics issue", body.client_payload);
  };
}

const opts = { secrets: [GITHUB_TOKEN] };
exports.fatal = onNewFatalIssuePublished(opts, forward("fatal"));
exports.nonfatal = onNewNonfatalIssuePublished(opts, forward("nonfatal"));
exports.anr = onNewAnrIssuePublished(opts, forward("anr"));
exports.regression = onRegressionAlertPublished(opts, forward("regression"));
